package com.ruoyi.ai.agent;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.ruoyi.ai.domain.dto.*;
import com.ruoyi.common.core.domain.R;
import com.ruoyi.common.core.context.SecurityContextHolder;
import junit.framework.TestCase;
import java.util.*;
import static com.ruoyi.ai.agent.AgentJson.*;

public class B10LegacyCompatibilityMysqlTest extends TestCase {
    private A1TestFixture f;private long book,branch;private String head;private CommitRequest initial;private final String a="{\"v\":1}",b="{\"v\":2}";
    protected void setUp() throws Exception {f=new A1TestFixture(true);book=f.seed("{\"v\":0}");initial=commitRequest(a);head=(String)f.tx.execute(tx->f.service.commit(book,initial)).getData().get("commitId");branch=((Number)state().get("branchId")).longValue();}
    protected void tearDown(){f.close();}
    private Map<String,Object> state(){return f.status(book);}
    private CommitRequest commitRequest(String content){Map<String,Object>s=state();Map<?,?>d=(Map<?,?>)s.get("workingState");CommitRequest r=new CommitRequest();r.setBranchId(((Number)s.get("branchId")).longValue());r.setBaseCommitId((String)s.get("headCommitId"));r.setBaseVersion(((Number)s.get("version")).longValue());r.setExpectedDraftVersion(d==null?-1L:((Number)d.get("version")).longValue());r.setLoadedRevision((String)s.get("loadedRevision"));r.setOperationId(UUID.randomUUID().toString());r.setCommitMessage("legacy compatibility");r.setSource("manual");r.setContent(content);r.setExecutedChanges(Collections.singletonList(Collections.singletonMap("kind",(Object)"manual")));return r;}
    private void draft(){CommitRequest x=commitRequest(b);WorkingStateRequest r=f.request(book,x.getExpectedDraftVersion(),x.getLoadedRevision(),b);r.setBaseCommitId(x.getBaseCommitId());r.setBaseVersion(x.getBaseVersion());assertEquals(200,f.save(book,r).getCode());}
    private void legacyCommit(String validation){f.db.update("update ai_workbook_commit set validation_json=? where commit_id=?",validation,head);}
    private ObjectNode receipt(){return obj().put("callId","legacy-call").put("claimToken","legacy-token").put("argsHash","legacy-args").put("fencingToken",1).put("ok",true).put("calculationVerified",true).set("snapshot",parse(a));}
    private String run(String status,ObjectNode request,boolean identity){String id=UUID.randomUUID().toString();ObjectNode call=obj().put("callId","legacy-call").put("status",status).put("claimToken","legacy-token").put("argsHash","legacy-args");if(identity)call.put("receiptHash",hash(request)).put("persistenceStatus","SAVED");ObjectNode r=obj().put("runId",id).put("workbookId",book).put("branchId",branch).put("userId",1).put("version",0).put("eventSeq",0).put("status","SUCCEEDED".equals(status)?"COMPLETED":"EXECUTING").put("fencingToken",1).put("revision",hash(parse(a))).put("persistenceStatus","SUCCEEDED".equals(status)?"SAVED":"UNVERIFIED").put("requestHash","private-request");r.set("call",call);r.set("initialSnapshot",parse(a));r.set("expectedSnapshot",parse(a));r.set("proposal",parse(a));r.set("unresolvedLegacyCall",call.deepCopy());f.db.update("insert into ai_agent_run(run_id,user_id,workbook_id,branch_id,request_id,request_hash,status,state_json,row_version,created_at,updated_at) values(?,?,?,?,?,?,?,?,0,now(3),now(3))",id,1,book,branch,UUID.randomUUID().toString(),hash(r),r.path("status").asText(),r.toString());f.db.update("insert into ai_agent_tool_call(run_id,call_id,status,args_hash,call_json) values(?,?,?,?,?)",id,"legacy-call",status,"legacy-args",call.toString());return id;}
    private void lease(String id){f.db.update("insert into ai_agent_lease(workbook_id,run_id,fencing_token,expires_at) values(?,?,1,?) on duplicate key update run_id=values(run_id),fencing_token=1,expires_at=values(expires_at)",book,id,System.currentTimeMillis()+120000);}
    private void sameWorkbook(String content){assertEquals(content,state().get("content"));assertEquals(head,state().get("headCommitId"));assertEquals(1,f.db.queryForObject("select count(*) from ai_workbook_commit where workbook_id=?",Integer.class,book).intValue());}
    public void testLegacyCommitMetadataNullEmptyAndOldShapeRemainReadable(){for(String validation:Arrays.asList(null,"{}","{\"hashVerified\":true}")){legacyCommit(validation);assertEquals(200,f.service.commitDetail(book,head).getCode());assertEquals(200,f.service.snapshot(book,head).getCode());assertEquals(a,f.service.snapshot(book,head).getData().get("content"));assertEquals(1,f.service.commits(book).getData().size());}sameWorkbook(a);}
    public void testLegacyHistoricalRestoreUsesServerSnapshotAndPreservesOriginal(){legacyCommit(null);CommitRequest r=commitRequest("{\"forged\":true}");R<Map<String,Object>> restored=f.tx.execute(tx->f.service.restore(book,head,r));assertEquals(200,restored.getCode());assertEquals(a,state().get("content"));assertEquals(a,f.service.snapshot(book,head).getData().get("content"));assertEquals(2,f.service.commits(book).getData().size());assertEquals("revert",f.service.commitDetail(book,(String)restored.getData().get("commitId")).getData().get("source"));}
    public void testLegacyOperationCannotBeReusedToConsumeLaterDraft(){legacyCommit(null);draft();assertEquals(409,f.tx.execute(tx->f.service.commit(book,initial)).getCode());sameWorkbook(b);}
    public void testCorruptLegacySnapshotRejectsReadAndRestore(){legacyCommit(null);f.db.update("update ai_workbook_snapshot set content_hash='bad' where commit_id=?",head);assertEquals(422,f.service.snapshot(book,head).getCode());CommitRequest r=commitRequest(a);assertEquals(422,f.tx.execute(tx->f.service.restore(book,head,r)).getCode());sameWorkbook(a);}
    public void testLegacyHistoryAndRunRemainOwnerScoped(){legacyCommit(null);ObjectNode req=receipt();String id=run("SUCCEEDED",req,true);SecurityContextHolder.setUserId("2");assertTrue(f.service.snapshot(book,head).getCode()!=200);assertTrue(f.service.commitDetail(book,head).getCode()!=200);try{f.runs.get(id,2);fail("foreign run read");}catch(IllegalArgumentException expected){}try{f.runs.receipt(id,2,req);fail("foreign receipt");}catch(IllegalArgumentException expected){}f.identity();sameWorkbook(a);}
    public void testLegacyRunReadSanitizesInternalSnapshotAndClaimFields(){String id=run("SUCCEEDED",receipt(),true);ObjectNode result=f.runs.get(id,1);assertEquals("COMPLETED",result.path("status").asText());for(String field:Arrays.asList("initialSnapshot","expectedSnapshot","proposal","requestHash"))assertFalse(result.has(field));assertFalse(result.path("call").has("claimToken"));assertFalse(result.path("unresolvedLegacyCall").has("claimToken"));sameWorkbook(a);}
    public void testIdenticalSavedReceiptReturnsHistoricalFactAndPreservesNewDraft(){ObjectNode req=receipt();String id=run("SUCCEEDED",req,true);draft();ObjectNode result=f.runs.receipt(id,1,req.deepCopy());assertEquals("COMPLETED",result.path("status").asText());assertEquals("SAVED",result.path("persistenceStatus").asText());sameWorkbook(b);assertEquals(0L,((Number)((Map<?,?>)state().get("workingState")).get("version")).longValue());}
    public void testChangedSavedReceiptCannotAlterOriginalFact(){ObjectNode req=receipt();String id=run("SUCCEEDED",req,true);draft();for(String field:Arrays.asList("claimToken","argsHash","snapshot","ok")){ObjectNode changed=req.deepCopy();if(field.equals("snapshot"))changed.set(field,parse(b));else if(field.equals("ok"))changed.put(field,false);else changed.put(field,"changed");try{f.runs.receipt(id,1,changed);fail("changed saved receipt accepted");}catch(IllegalArgumentException expected){}}sameWorkbook(b);assertEquals("COMPLETED",f.runs.get(id,1).path("status").asText());}
    public void testLegacySavedCallWithoutReceiptIdentityIsReadableButNotReplayable(){ObjectNode req=receipt();String id=run("SUCCEEDED",req,false);assertEquals("COMPLETED",f.runs.get(id,1).path("status").asText());try{f.runs.receipt(id,1,req);fail("unbound saved receipt");}catch(IllegalArgumentException expected){}sameWorkbook(a);}
    public void testNewLegacySuccessAndClaimRemainBlockedEvenWithLiveLease(){ObjectNode req=receipt();String id=run("CLAIMED",req,false);lease(id);try{f.runs.receipt(id,1,req);fail("new Snapshot saved");}catch(IllegalArgumentException expected){assertTrue(expected.getMessage().contains("SNAPSHOT_WRITE_BLOCKED"));}try{f.runs.claim(id,1,obj().put("clientId","legacy").put("fencingToken",1));fail("legacy claim");}catch(IllegalArgumentException expected){assertTrue(expected.getMessage().contains("SNAPSHOT_WRITE_BLOCKED"));}sameWorkbook(a);assertNull(state().get("workingState"));}
    public void testFailedLegacyReceiptBecomesUnknownNeverSavedAndCannotReplay(){ObjectNode req=receipt();String id=run("CLAIMED",req,false);lease(id);req.put("ok",false);ObjectNode result=f.runs.receipt(id,1,req);assertEquals("PAUSED",result.path("status").asText());assertEquals("UNKNOWN",result.path("call").path("status").asText());assertEquals("UNVERIFIED",result.path("persistenceStatus").asText());try{f.runs.receipt(id,1,req);fail("unknown re-receipt");}catch(IllegalArgumentException expected){}sameWorkbook(a);assertNull(state().get("workingState"));}
    public void testReadingOldSavedReceiptCannotReleaseAnotherActiveLease(){ObjectNode req=receipt();String id=run("SUCCEEDED",req,true);draft();String other=UUID.randomUUID().toString();lease(other);f.runs.receipt(id,1,req);assertEquals(other,f.db.queryForObject("select run_id from ai_agent_lease where workbook_id=?",String.class,book));sameWorkbook(b);}
}
